    //   'R': x[k+1] = x[k] + 1
    //   'L': x[k+1] = x[k] - 1
    //   'U': y[k+1] = y[k] + 1
    //   'D': y[k+1] = y[k] - 1
    //
    // A substring from i to j (0-indexed, inclusive) corresponds to executing commands s[i], s[i+1], ..., s[j].
    // The net displacement is (x[j+1] - x[i], y[j+1] - y[i]).
    // We want x[j+1] - x[i] = 0 and y[j+1] - y[i] = 0.
    // So x[j+1] = x[i] and y[j+1] = y[i].
    //
    // Let's create an array of prefix positions: pos[0] = (0,0), pos[1] = (x1, y1), ..., pos[n] = (xn, yn).
    // We need to count pairs (i, j) such that 0 <= i < j <= n and pos[i] == pos[j].
    // Note: The substring is non-empty, so i < j. The substring starts at index i and ends at index j-1.
    //
    // So we can use a map to count the frequency of each (x, y) position in the prefix array.
    // For each position (x, y) that appears k times, the number of pairs is k * (k - 1) / 2.

    const prefixX = new Array(n + 1);
    const prefixY = new Array(n + 1);
    prefixX[0] = 0;
    prefixY[0] = 0;

    for (let i = 0; i < n; i++) {
        prefixX[i + 1] = prefixX[i];
        prefixY[i + 1] = prefixY[i];
        switch (s[i]) {
            case 'R':
                prefixX[i + 1] += 1;
                break;
            case 'L':
                prefixX[i + 1] -= 1;
                break;
            case 'U':
                prefixY[i + 1] += 1;
                break;
            case 'D':
                prefixY[i + 1] -= 1;
                break;
